<script setup lang="ts">
import { seededShuffle } from '../domain/rules'
import { computed,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { usePlatform } from '../stores/platform'
import { useProtocol } from '../stores/protocol'
import { exchangeSamples,type ExchangeSystem } from '../domain/protocol'
import { csv,download } from '../utils/files'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
const s=usePlatform(),p=useProtocol(),route=useRoute(),router=useRouter(),page=computed(()=>String(route.params.id))
const titles:Record<string,string>={development:'命题质量与计划统计',papers:'试卷配发与使用追溯',examination:'考试管控配置',marking:'阅卷任务分配',skills:'技能考核任务与成绩',integration:'业务数据模拟交换'}
const reportOpen=ref(false),distributionOpen=ref(false),reviewOpen=ref(false),skillOpen=ref(false),exchangeOpen=ref(false)
const paperId=ref(s.data.papers.find(x=>x.status!=='草稿')?.id||''),batch=ref('2026年第四季度等级认定'),receiver=ref('模拟第一单位')
const markId=ref(s.data.marks.find(m=>!Object.keys(m.scores).length)?.id||''),reviewCount=ref(2)
const questionThresholds=ref<number[]>([]),markView=ref('按试卷')
const reviewMark=computed(()=>s.data.marks.find(m=>m.id===markId.value))
function loadThresholds(){questionThresholds.value=reviewMark.value?.rubric.map(()=>s.data.settings.threshold)||[]}
const reviewPeople=ref(['reviewer1','reviewer2']),arbitrator=ref('arbitrator'),thresholdScope=ref<'整卷'|'逐题'>('整卷')
function randomReview(){reviewPeople.value=seededShuffle(s.people.filter(p=>p.enabled&&p.duties.includes('review')&&p.reviewer).map(p=>p.id),Date.now()).slice(0,reviewCount.value)}
const skillForm=ref({sessionId:'EXAM-001',level:'三级 / 高级工',module:'',questionId:'SK-1',candidate:'演示考生01',batch:'2026年第四季度技能考核',venue:'技能考场 · 工位A01',assessor:'钱考评',profession:'航空发动机装配工'}),skillDetail=ref('')
const system=ref<ExchangeSystem>('集团HR'),sample=computed(()=>exchangeSamples[system.value]),policy=ref({...p.data.policy}),checkIp=ref('192.168.10.12'),ipResult=ref('')
const skillQuestions=computed(()=>s.data.questions.filter(q=>q.kind==='技能'&&q.status==='已入库'&&q.profession===skillForm.value.profession&&q.level===skillForm.value.level&&(!skillForm.value.module||q.module===skillForm.value.module)))
const pickedSkill=computed(()=>s.data.questions.find(q=>q.id===skillForm.value.questionId))
const selectedSkill=computed(()=>s.data.skills.find(k=>k.id===skillDetail.value))
const scopedPlans=computed(()=>s.data.plans.filter(plan=>s.can('development')||plan.leadId===s.personId))
const scopedQuestions=computed(()=>s.data.questions.filter(q=>s.can('development')||scopedPlans.value.some(p=>p.id===q.taskId)))
const duplicates=computed(()=>{const groups=new Map<string,typeof s.data.questions>();for(const q of scopedQuestions.value){const text=q.title.replace(/\s/g,'');const list=groups.get(text)||[];list.push(q);groups.set(text,list)}return [...groups.values()].filter(g=>g.length>1)})
const expertStats=computed(()=>s.data.experts.map(e=>{const qs=scopedQuestions.value.filter(q=>q.author===e.name);return {name:e.name,count:qs.length,approved:qs.filter(q=>q.status==='已入库').length,returned:qs.filter(q=>q.history.some(h=>h.action.includes('退回'))).length}}))
function exportDevelopment(){csv('命题计划完成情况.csv',[['计划','专家','目标题量','已关联','已入库','状态'],...scopedPlans.value.map(plan=>[plan.name,plan.expert,plan.target,s.data.questions.filter(q=>q.taskId===plan.id).length,s.data.questions.filter(q=>q.taskId===plan.id&&q.status==='已入库').length,plan.status])]);s.audit('命题统计','导出计划报表','全部计划')}
function exportExperts(){csv('专家命题工作量.csv',[['专家','命制量','当前入库量','曾退回题数'],...expertStats.value.map(e=>[e.name,e.count,e.approved,e.returned])]);s.audit('命题统计','导出专家工作量','全部专家')}
function distribute(){s.run(()=>{p.distribute(paperId.value,batch.value,receiver.value);distributionOpen.value=false})}
function paperText(id:string){s.run(()=>{const paper=s.data.papers.find(x=>x.id===id);if(!paper)throw new Error('试卷不存在');download(paper.name+'-考生卷.txt',[paper.name,'合成演示试卷，不包含标准答案',...paper.questions.map((item,i)=>`${i+1}. ${item.question.title}（${item.score}分）\n${item.question.options.map((o,j)=>String.fromCharCode(65+j)+'. '+o).join('\n')}`)].join('\n\n'));s.audit('试卷配发','下载考生卷',id)})}
function saveReview(){s.run(()=>{p.assignReview(markId.value,reviewCount.value,reviewPeople.value,arbitrator.value,thresholdScope.value,questionThresholds.value);reviewOpen.value=false})}
function dispatch(){s.run(()=>{p.dispatchSkill(skillForm.value.questionId,skillForm.value.candidate,skillForm.value.batch,skillForm.value.venue,skillForm.value.assessor,skillForm.value.sessionId);skillOpen.value=false})}
function randomSkill(){s.run(()=>{skillForm.value.questionId=p.randomSkill(skillForm.value.profession,skillForm.value.level,skillForm.value.module);s.notify('已按工种抽取一条已入库技能题，请核对准备要求')})}
function prepare(){s.run(()=>{const q=pickedSkill.value;if(!q)throw new Error('请选择技能题');download(q.title+'-准备要求.txt',[q.title,'考生准备：'+q.preparation,'考场准备：'+q.venue,'考核要求：'+q.analysis,...q.rubric.map(r=>r.label+'：'+r.max+'分')].join('\n'));s.audit('技能考核','下载准备要求',q.id)})}
function exportSkills(){csv('技能成绩.csv',[['任务','批次','考生','题号','分数','状态','考评人员'],...s.data.skills.map(k=>[k.id,k.batch||'预置模拟场',k.candidate,k.questionId,k.status==='已提交'?k.scores.reduce((a,b)=>a+b,0):'待评分',k.status,s.people.find(u=>u.id===k.assessorId)?.name||k.assessor||''])]);s.audit('技能考核','导出技能成绩','现场任务')}
function ipNumber(ip:string){const parts=ip.split('.');if(parts.length!==4||parts.some(p=>!/^\d{1,3}$/.test(p)||Number(p)>255))throw new Error('请输入合法IPv4地址');return parts.reduce((v,n)=>(v<<8)|Number(n),0)>>>0}
function ipRule(){const [network,bits]=policy.value.ipRange.trim().split('/');if(bits===undefined||!/^\d+$/.test(bits)||Number(bits)>32)throw new Error('IP范围请使用IPv4/CIDR格式，如192.168.10.0/24');return {network:ipNumber(network!),mask:(Number(bits)===0?0:(0xffffffff<<(32-Number(bits))))>>>0}}
function savePolicy(){s.run(()=>{s.requireDuty('affairs');ipRule();if(!Number.isInteger(policy.value.faceInterval)||policy.value.faceInterval<1||policy.value.faceInterval>60)throw new Error('考中识别间隔为1～60分钟');p.data.policy={...policy.value};s.data.settings.faceInterval=policy.value.faceInterval;s.audit('考试管控','保存模拟策略','全局演示策略');s.notify('模拟策略已保存，未启用系统级安全拦截')})}
function evaluateIp(){s.run(()=>{const rule=ipRule();ipResult.value=(ipNumber(checkIp.value)&rule.mask)===(rule.network&rule.mask)?'模拟判定：在允许范围内':'模拟判定：不在允许范围内'})}
function applyExchange(){s.run(()=>{p.applyExchange(system.value);exchangeOpen.value=false})}
function share(){s.run(()=>{const record=p.sharePublic();download('公开资源共享样例.json',JSON.stringify({record,questions:s.data.questions.filter(q=>record.objects.includes(q.id))},null,2),'application/json');s.notify('已生成合成共享样例及发送回执')})}
</script>
<template><PageHead :title="titles[page]||'业务工作区'" subtitle="" eyebrow="业务管理"/>

<template v-if="page==='development'"><div class="mini-metrics"><div><span>命题计划</span><strong>{{scopedPlans.length}}</strong></div><div><span>当前入库题</span><strong>{{scopedQuestions.filter(q=>q.status==='已入库').length}}</strong></div><div><span>待审核</span><strong>{{scopedQuestions.filter(q=>q.status.startsWith('待')).length}}</strong></div><div><span>完全同文题组</span><strong>{{duplicates.length}}</strong></div></div><section class="panel"><div class="panel-head"><h3>计划完成情况</h3><div class="inline-actions"><button class="button small" @click="reportOpen=true;s.audit('命题质量','同文检测','全部题目')">执行同文检测</button><button class="button small" @click="exportDevelopment">导出计划报表</button></div></div><div class="table-scroll"><table><thead><tr><th>命题计划</th><th>专家</th><th>目标题量</th><th>已关联 / 已入库</th><th>状态</th></tr></thead><tbody><tr v-for="plan in scopedPlans"><td>{{plan.name}}</td><td>{{plan.expert}}</td><td>{{plan.target}}</td><td>{{s.data.questions.filter(q=>q.taskId===plan.id).length}} / {{s.data.questions.filter(q=>q.taskId===plan.id&&q.status==='已入库').length}}</td><td><Badge :text="plan.status"/></td></tr></tbody></table></div></section><section class="panel spaced"><div class="panel-head"><h3>专家工作量 · 由当前试题计算</h3><button class="button small" @click="exportExperts">导出专家报表</button></div><table><thead><tr><th>专家</th><th>命制量</th><th>当前入库量</th><th>曾退回题数</th></tr></thead><tbody><tr v-for="e in expertStats"><td>{{e.name}}</td><td>{{e.count}}</td><td>{{e.approved}}</td><td>{{e.returned}}</td></tr></tbody></table></section></template>
<template v-if="page==='papers'"><section class="panel"><div class="panel-head"><h3>传统考试配发记录</h3><button class="button primary" @click="distributionOpen=true">登记传统考试配发</button></div><div class="table-scroll"><table><thead><tr><th>批次 / 单位</th><th>试卷</th><th>配发时间</th><th>操作</th></tr></thead><tbody><tr v-for="d in p.data.distributions"><td>{{d.batch}}<small>{{d.receiver}}</small></td><td>{{s.data.papers.find(x=>x.id===d.paperId)?.name}}<small>{{d.id}}</small></td><td>{{d.time}}</td><td><button class="text-button" @click="paperText(d.paperId)">下载考生卷</button></td></tr></tbody></table></div><Empty v-if="!p.data.distributions.length" title="暂无传统考试配发" description="选择预置冻结试卷登记一条配发记录。"/></section><section class="panel spaced"><div class="panel-head"><h3>机考场次与试卷使用</h3><RouterLink class="button small" to="/affairs/sessions">进入场次配卷</RouterLink></div><table><thead><tr><th>场次</th><th>试卷</th><th>答卷数量</th><th>操作</th></tr></thead><tbody><tr v-for="exam in s.data.sessions"><td>{{exam.name}}</td><td>{{s.data.papers.find(x=>x.id===exam.paperId)?.name||'待配卷'}}</td><td>{{s.data.attempts.filter(a=>a.sessionId===exam.id).length}}</td><td><button v-if="exam.paperId" class="text-button" @click="paperText(exam.paperId)">下载考生卷</button></td></tr></tbody></table></section><div class="notice spaced">下载为不含答案的文本考生卷；版式打印请进入组卷管理预览试卷。配发记录与机考场次均引用已有试卷。</div></template>
<template v-if="page==='examination'"><section class="panel protocol-form"><h3>考试安全与准入策略 · 模拟配置</h3><div class="form-grid"><label>允许IP范围<input v-model="policy.ipRange" placeholder="192.168.10.0/24"/></label><label>考中人脸间隔（分钟）<input v-model.number="policy.faceInterval" type="number" min="1" max="60"/></label><label v-for="item in [{key:'faceBefore',label:'考前人脸核验'},{key:'faceDuring',label:'考中人脸核验'},{key:'faceAfter',label:'考后人脸核验'},{key:'preventSwitch',label:'防切屏策略'},{key:'bindSeat',label:'机位绑定策略'}]" class="checkbox-label"><input type="checkbox" v-model="policy[item.key as 'faceBefore']"/>{{item.label}}</label></div><div class="notice">考试时间规则：迟到超过30分钟禁止作答，开考15分钟内禁止交卷。真实人脸识别、IP网关、系统级拦截不在浏览器中执行。</div><button class="button primary" @click="savePolicy">保存模拟考试策略</button></section><section class="panel protocol-form spaced"><h3>IP规则样例检查</h3><div class="filter-bar wrap"><input v-model="checkIp" aria-label="待检查IP"/><button class="button" @click="evaluateIp">检查IP样例</button><span>{{ipResult}}</span></div></section></template>
<template v-if="page==='marking'"><section class="panel"><div class="panel-head"><h3>评分小组与任务</h3><button class="button primary" @click="reviewOpen=true">分配阅卷任务</button></div><div class="filter-bar"><label class="inline-label">查看方式<select v-model="markView"><option>按试卷</option><option>按考生</option><option>按试题</option></select></label></div><div class="table-scroll"><table><thead><tr><th>{{markView==='按考生'?'考生 / 答卷':'匿名答卷'}}</th><th>评阅内容</th><th>模拟评委</th><th>已提交</th><th>状态</th></tr></thead><tbody><tr v-for="m in s.data.marks"><td><template v-if="markView==='按考生'">{{s.data.attempts.find(a=>a.id===m.attemptId)?.candidate||'历史匿名考生'}}<br/></template>{{m.anonymous}}</td><td><template v-if="markView==='按试题'"><p v-for="(q,i) in m.rubric">{{i+1}}. {{q.label}} · {{m.finalDetails?.[i]??'待核定'}} / {{q.max}}</p></template><template v-else>{{m.title}}</template></td><td>{{m.reviewers?.join('、')||'按全局规则使用预置评委'}}</td><td>{{Object.keys(m.scores).length}}人</td><td><Badge :text="m.status"/></td></tr></tbody></table></div></section><div class="notice spaced">可为未评分任务配置一判、双判、三判；开始评分后禁止直接改变评委。待仲裁任务可在评分角色下退回重评，原分数留痕。评分绑定当前演示人员，不连接真实身份系统。</div></template>
<template v-if="page==='skills'"><section class="panel"><div class="panel-head"><h3>现场考核任务</h3><div class="inline-actions"><button class="button small" @click="exportSkills">导出技能成绩</button><button class="button primary" @click="skillOpen=true">抽题并配发技能任务</button></div></div><div class="table-scroll"><table><thead><tr><th>考生 / 批次</th><th>试题 / 工位</th><th>状态</th><th>总分</th><th>操作</th></tr></thead><tbody><tr v-for="k in s.data.skills"><td>{{k.candidate}}<small>{{k.batch||'预置模拟考核批次'}}</small></td><td>{{k.questionId}}<small>{{k.venue||'技能考场A01'}}</small></td><td><Badge :text="k.status"/></td><td>{{k.status==='已提交'?k.scores.reduce((a,b)=>a+b,0):'待评分'}}</td><td><button class="text-button" @click="skillDetail=k.id">查看明细</button></td></tr></tbody></table></div></section></template>
<template v-if="page==='integration'"><div class="integration-grid"><article v-for="(value,key) in exchangeSamples" class="panel integration-card"><span class="icon-circle blue"><Icon name="Cable"/></span><h3>{{key}}</h3><p>{{value.description}}</p><button class="button primary" @click="system=key;exchangeOpen=true">预览交换样例</button></article><article class="panel integration-card"><span class="icon-circle violet"><Icon name="Upload"/></span><h3>公开资源共享</h3><p>选择3道已入库通用题，生成合成共享包和模拟发送回执。</p><button class="button" @click="share">导出共享样例</button></article></div><section class="panel spaced"><div class="panel-head"><h3>已同步员工主数据</h3><Badge text="全部为合成人员"/></div><div class="table-scroll"><table><thead><tr><th>员工编码</th><th>姓名</th><th>身份标识</th><th>工种 / 等级</th><th>来源</th></tr></thead><tbody><tr v-for="person in p.data.staff"><td>{{person.id}}</td><td>{{person.name}}</td><td>{{person.identity}}</td><td>{{person.profession}}<small>{{person.level}}</small></td><td>{{person.source}}</td></tr></tbody></table></div></section><section class="panel spaced"><div class="panel-head"><h3>本轮交换与业务对象</h3><RouterLink class="button small" to="/support/integrations">全部回执与重试</RouterLink></div><div class="table-scroll"><table><thead><tr><th>系统</th><th>来源版本键</th><th>写入或共享对象</th><th>时间</th></tr></thead><tbody><tr v-for="e in p.data.exchanges"><td>{{e.system}}</td><td>{{e.key}}</td><td>{{e.objects.join('、')}}</td><td>{{e.time}}</td></tr></tbody></table></div><Empty v-if="!p.data.exchanges.length"/></section><div class="notice spaced">确认模拟同步会实际更新本地员工、场次、命题计划或题库。固定来源版本重复同步不重复创建；未连接任何真实外部系统。</div></template>
<Modal v-if="reportOpen" title="题目同文检测报告" wide @close="reportOpen=false"><div class="notice">按题干去除空白后完全一致分组。当前仅实现完全同文检测，不代表语义、图片相似度检测。重复组数：{{duplicates.length}}。</div><div v-for="group in duplicates" class="history-row"><div><h4>{{group[0]?.title}}</h4><p>{{group.map(q=>q.id).join('、')}}</p></div><RouterLink class="button small" to="/bank/questions">进入题库处理</RouterLink></div><Empty v-if="!duplicates.length" title="未发现完全同文题" description="检测来自当前题库，不自动删除资源。"/></Modal>
<Modal v-if="distributionOpen" title="传统考试试卷配发" @close="distributionOpen=false"><label class="field">冻结试卷<select v-model="paperId"><option v-for="paper in s.data.papers.filter(x=>x.status!=='草稿')" :value="paper.id">{{paper.name}}</option></select></label><label class="field">配发批次<input v-model="batch"/></label><label class="field">接收单位<input v-model="receiver"/></label><template #footer><button class="button primary" @click="distribute">确认登记配发</button></template></Modal>
<Modal v-if="reviewOpen" title="配置模拟评分小组" @close="reviewOpen=false"><label class="field">未评分答卷<select v-model="markId" @change="loadThresholds"><option v-for="m in s.data.marks.filter(m=>!Object.keys(m.scores).length&&!['已核定','已发布'].includes(m.status))" :value="m.id">{{m.anonymous}} · {{m.title}}</option></select></label><label class="field">判分模式<select v-model.number="reviewCount" @change="randomReview"><option :value="1">一判</option><option :value="2">双判</option><option :value="3">三判</option></select></label><div class="notice">核分规则：{{s.data.settings.scoreRule}}。去极值须三判，当前权重模板须双判。</div><h3>评分小组</h3><div class="filter-bar"><label v-for="person in s.people.filter(p=>p.enabled&&p.duties.includes('review')&&p.reviewer)" class="checkbox-label"><input type="checkbox" v-model="reviewPeople" :value="person.id"/>{{person.name}} · {{person.reviewer}}</label><button class="button" @click="randomReview">随机分配人员</button></div><label class="field">仲裁人员<select v-model="arbitrator"><option v-for="person in s.people.filter(p=>p.enabled&&p.duties.includes('arbitrate'))" :value="person.id">{{person.name}}</option></select></label><label class="field">分差判断方式<select v-model="thresholdScope" @change="loadThresholds"><option>整卷</option><option>逐题</option></select></label><div v-if="thresholdScope==='逐题'"><label v-for="(item,i) in reviewMark?.rubric" class="field">{{item.label}} · 差值阈值<input type="number" min="0" v-model.number="questionThresholds[i]"/></label></div><p class="muted">权重按照所选评委顺序绑定，不受评分提交先后影响。已评分任务须先仲裁退回，才能重新分配。</p><template #footer><button class="button primary" @click="saveReview">保存任务分配</button></template></Modal>
<Modal v-if="skillOpen" title="技能抽题与任务配发" wide @close="skillOpen=false"><div class="form-grid"><label>职业工种<select v-model="skillForm.profession" @change="skillForm.questionId=skillQuestions[0]?.id||''"><option v-for="job in [...new Set(s.data.questions.filter(q=>q.kind==='技能').map(q=>q.profession))]">{{job}}</option></select></label><label>等级<select v-model="skillForm.level" @change="skillForm.questionId=''"><option v-for="level in [...new Set(s.data.questions.filter(q=>q.kind==='技能').map(q=>q.level))]">{{level}}</option></select></label><label>技能模块<select v-model="skillForm.module" @change="skillForm.questionId=''"><option value="">全部模块</option><option v-for="module in [...new Set(s.data.questions.filter(q=>q.kind==='技能'&&q.profession===skillForm.profession).map(q=>q.module))]">{{module}}</option></select></label><label>指定技能题<select v-model="skillForm.questionId"><option v-for="q in skillQuestions" :value="q.id">{{q.id}} · {{q.title}}</option></select></label><label>考试场次<select v-model="skillForm.sessionId" @change="skillForm.candidate=''"><option v-for="e in s.data.sessions" :value="e.id">{{e.name}}</option></select></label><label>考生<select v-model="skillForm.candidate"><option v-for="e in s.data.continuity!.enrollments.filter(e=>e.sessionId===skillForm.sessionId)">{{e.name}}</option></select></label><label>考核批次<input v-model="skillForm.batch"/></label><label>考场与工位<input v-model="skillForm.venue"/></label><label>考评员<select v-model="skillForm.assessor"><option v-for="e in s.people.filter(u=>u.enabled&&u.duties.includes('skill'))">{{e.name}}</option></select></label></div><div v-if="pickedSkill" class="notice"><strong>{{pickedSkill.title}}</strong><p>考生准备：{{pickedSkill.preparation}}</p><p>考场准备：{{pickedSkill.venue}}</p><p>考核要求：{{pickedSkill.analysis}}</p><p>评分标准：{{pickedSkill.rubric.map(r=>r.label+' '+r.max+'分').join('；')}}</p></div><template #footer><button class="button" @click="randomSkill">按模块随机抽题</button><button class="button" @click="prepare">下载准备要求</button><button class="button primary" @click="dispatch">确认配发技能任务</button></template></Modal>
<Modal v-if="selectedSkill" title="现场评分与任务明细" @close="skillDetail=''"><div class="detail-grid"><div><small>考生</small><strong>{{selectedSkill.candidate}}</strong></div><div><small>状态</small><Badge :text="selectedSkill.status"/></div><div><small>任务来源</small><strong>{{selectedSkill.source||'预置合成任务'}}</strong></div><div><small>考评员</small><strong>{{selectedSkill.assessor||'陈工'}}</strong></div></div><p v-for="(score,i) in selectedSkill.scores">第{{i+1}}项：{{selectedSkill.status==='已提交'?score:'待评分'}}</p><p>操作人员：{{s.people.find(u=>u.id===selectedSkill!.assessorId)?.name||'待分配'}}</p><p>评价：{{selectedSkill.note||'无'}}</p></Modal>
<Modal v-if="exchangeOpen" :title="system+' · 交换预览'" wide @close="exchangeOpen=false"><div class="notice">{{sample.description}}<br/>来源版本键：{{sample.key}}</div><table><thead><tr><th>外部示例字段</th><th>内部含义</th></tr></thead><tbody><tr v-for="field in sample.fields"><td>{{field[0]}}</td><td>{{field[1]}}</td></tr></tbody></table><pre class="protocol-json">{{JSON.stringify(sample.rows,null,2)}}</pre><template #footer><button class="button" @click="exchangeOpen=false">取消</button><button class="button primary" @click="applyExchange">确认模拟同步</button></template></Modal>
</template>
